import AnyLanguageModel

/// The result of applying one compaction policy.
///
/// `Output` is the value generated by the model. Hail does not interpret its
/// fields. `archivedCount` is runtime metadata computed by the compaction
/// policy and is replayed against the event-sourced conversation state.
public struct CompactionResult<Output: Codable & Sendable & Generable>: Codable, Sendable {
    public let output: Output
    public let archivedCount: Int

    public init(output: Output, archivedCount: Int) {
        self.output = output
        self.archivedCount = archivedCount
    }
}

extension CompactionResult: Equatable where Output: Equatable {}
